package teamroots.goetia.hiddentest;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.CameraType;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.BlockPos;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.Difficulty;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.LevelSettings;
import net.minecraft.world.level.WorldDataConfiguration;
import net.minecraft.world.level.levelgen.WorldOptions;
import net.minecraft.world.level.levelgen.presets.WorldPresets;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import teamroots.goetia.*;
import teamroots.goetia.client.GoetiaScreen;
@EventBusSubscriber(modid="goetia",value=Dist.CLIENT)
public final class GoetiaHarness {
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger("goetia.test");
 private record Step(String name,int delay,java.util.function.Function<Minecraft,CompletableFuture<Void>> run){}
 private static final List<Step> STEPS=new ArrayList<>();private static final List<GoetiaSymbol> SYMBOLS=new ArrayList<>();private static final AtomicInteger FAILURES=new AtomicInteger();private static CompletableFuture<Void> pending;private static boolean creating,built,done;private static int index,wait=60,checks,shots,startupTicks;private static String startupScreen="";private static int fireballId;private static volatile net.minecraft.world.phys.Vec3 redirectedPower;
 private static void check(boolean value,String text){checks++;if(!value)throw new AssertionError(text);LOG.info("GOETIA_CHECK {}",text);}
 private static void client(String name,int delay,Consumer<Minecraft> fn){STEPS.add(new Step(name,delay,mc->{fn.accept(mc);return CompletableFuture.completedFuture(null);}));}
 private static void server(String name,int delay,Consumer<MinecraftServer> fn){STEPS.add(new Step(name,delay,mc->{var future=new CompletableFuture<Void>();var srv=mc.getSingleplayerServer();if(srv==null)throw new AssertionError("Expected isolated integrated server");srv.execute(()->{try{fn.accept(srv);future.complete(null);}catch(Throwable t){FAILURES.incrementAndGet();LOG.error("GOETIA_TEST_FAILED server "+name,t);future.complete(null);}});return future;}));}
 private static void shot(String name){client("screenshot "+name,10,mc->{Screenshot.grab(mc.gameDirectory,name+".png",mc.gameRenderer.mainRenderTarget(),1,c->{});shots++;});}
 private static net.minecraft.server.level.ServerPlayer player(MinecraftServer server){var id=Minecraft.getInstance().player.getUUID();return server.getPlayerList().getPlayer(id);}
 private static void journal(Minecraft mc,String state){try{var path=mc.gameDirectory.toPath().resolve("goetia-test-progress.json");var tmp=path.resolveSibling("goetia-test-progress.writing");String json="{\"state\":\""+state+"\",\"step\":"+index+",\"total\":"+STEPS.size()+",\"failures\":"+FAILURES.get()+",\"checks\":"+checks+",\"screenshots\":"+shots+"}";Files.writeString(tmp,json);Files.move(tmp,path,java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){throw new IllegalStateException(e);}}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("goetia.autotest"))return;var mc=Minecraft.getInstance();if(mc.level==null||mc.player==null){String screen=mc.gui.screen()==null?"none":mc.gui.screen().getClass().getName();if(!screen.equals(startupScreen)){startupScreen=screen;LOG.info("GOETIA_STARTUP_SCREEN {}",screen);journal(mc,"starting");}if(mc.gui.screen() instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen){mc.options.onboardingAccessibilityFinished();mc.gui.setScreen(new TitleScreen());}if(++startupTicks>6000){FAILURES.incrementAndGet();LOG.error("GOETIA_TEST_FAILED startup timeout screen={}",screen);journal(mc,"failed");mc.stop();return;}if(!creating&&mc.gui.screen() instanceof TitleScreen title){creating=true;mc.options.framerateLimit().set(30);mc.options.pauseOnLostFocus=false;mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).set(0.0);String name="goetia-check-"+System.currentTimeMillis();var settings=new LevelSettings(name,GameType.CREATIVE,new LevelSettings.DifficultySettings(Difficulty.NORMAL,false,false),true,WorldDataConfiguration.DEFAULT);mc.createWorldOpenFlows().createFreshLevel(name,settings,new WorldOptions(20261114L,true,false),registries->registries.lookupOrThrow(net.minecraft.core.registries.Registries.WORLD_PRESET).getOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),title);}return;}
  if(!built){built=true;build();journal(mc,"running");}if(pending!=null&&!pending.isDone())return;if(wait-->0)return;if(index>=STEPS.size()){if(!done){done=true;LOG.info("GOETIA_TEST_{} checks={} screenshots={}",FAILURES.get()==0?"PASS":"FAIL",checks,shots);LOG.info("GOETIA_TEST_DONE");journal(mc,FAILURES.get()==0?"passed":"failed");wait=20;}else mc.stop();return;}var step=STEPS.get(index++);LOG.info("GOETIA_TEST_STEP {}/{} {}",index,STEPS.size(),step.name);try{pending=step.run.apply(mc);}catch(Throwable t){FAILURES.incrementAndGet();LOG.error("GOETIA_TEST_FAILED client "+step.name,t);}wait=step.delay;journal(mc,"running");
 }
 private static void build(){
  server("prepare private scene",80,srv->{var p=player(srv);var w=p.level();for(int x=-14;x<=14;x++)for(int z=-10;z<=12;z++){w.setBlockAndUpdate(new BlockPos(x,100,z),Blocks.SMOOTH_STONE.defaultBlockState());for(int y=101;y<=106;y++)w.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState());}p.teleportTo(w,0,101,10,java.util.Set.of(),180,5,false);w.dimensionType().defaultClock().ifPresent(clock->srv.clockManager().setTotalTicks(clock,6000));for(int i=0;i<3;i++){var d=GoetiaEntities.DEMONS.get(i).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);d.setNoAi(true);d.setPos(-4+i*4,101,0);w.addFreshEntity(d);}for(int i=0;i<6;i++){var symbol=GoetiaEntities.SYMBOLS.get(i).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);symbol.setPos(-7.5+i*3,101,-5);w.addFreshEntity(symbol);SYMBOLS.add(symbol);}p.experienceLevel=100;check(SYMBOLS.size()==6,"six registered symbols in scene");});
  shot("goetia_mobs_and_symbols");
  server("activate all symbols",45,srv->{var p=player(srv);for(var s:SYMBOLS)check(s.activate(p),"activate "+s.kind);});shot("goetia_symbols_charging");
  server("overhead symbol view",20,srv->{var p=player(srv);p.getAbilities().flying=true;p.onUpdateAbilities();p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.teleportTo(p.level(),0,109,8,java.util.Set.of(),180,48,false);});shot("goetia_symbols_overhead");
  server("return to front view",10,srv->{var p=player(srv);p.getAbilities().flying=false;p.onUpdateAbilities();p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.teleportTo(p.level(),0,101,10,java.util.Set.of(),180,5,false);});
  server("focus eligibility",20,srv->{var p=player(srv);GoetiaPlayer.set(p,"purity",0);GoetiaPlayer.set(p,"impurity",30);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("soul_focus")));});
  client("open original focus",10,mc->mc.gui.setScreen(new GoetiaScreen("focus",InteractionHand.MAIN_HAND)));shot("goetia_focus");
  client("cast actual drag gesture",20,mc->{var screen=(GoetiaScreen)mc.gui.screen();int[] sequence={1,6,3,4};for(int j=0;j<sequence.length;j++){int i=sequence[j]-1;double x=screen.width/2.0+80*Math.cos(i/6.0*Math.PI*2-Math.PI/2),y=screen.height/2.0+80*Math.sin(i/6.0*Math.PI*2-Math.PI/2);if(j==0)screen.mouseClicked(mouse(x,y,0),false);else screen.mouseDragged(mouse(x,y,0),0,0);}screen.mouseReleased(mouse(0,0,0));});
  server("gesture reached server",10,srv->{var p=player(srv);check(GoetiaPlayer.data(p).getIntOr("burning_touch",0)>0,"focus gesture casts on server");check(GoetiaPlayer.data(p).getIntOr("impurity",0)==30,"focus cast spends no alignment");});
  server("teach and equip chalk",20,srv->{var p=player(srv);GoetiaPlayer.learn(p,"impSymbol");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("demonic_chalk")));});
  client("knowledge synchronized",10,mc->{check(GoetiaPlayer.knowledge(mc.player).contains("impSymbol"),"owner receives knowledge");mc.gui.setScreen(new GoetiaScreen("chalk",InteractionHand.MAIN_HAND));});shot("goetia_chalk");
  client("select known symbol",20,mc->{var screen=(GoetiaScreen)mc.gui.screen();screen.mouseClicked(mouse(screen.width/2.0,screen.height/2.0-80,0),false);mc.gui.setScreen(null);});
  server("selection reached server",10,srv->check(GoetiaItem.tag(player(srv).getMainHandItem()).getStringOr("knowledge","").equals("impSymbol"),"chalk selection reaches server"));
  server("angel spell reference",20,srv->{var p=player(srv);GoetiaPlayer.set(p,"impurity",0);GoetiaPlayer.set(p,"purity",1000);});
  client("open altar reference",10,mc->mc.gui.setScreen(new GoetiaScreen("altar",InteractionHand.MAIN_HAND)));shot("goetia_altar_spells");
  client("close reference and front camera",20,mc->{mc.gui.setScreen(null);mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});shot("goetia_angel_aura");
  server("demon transformation",20,srv->{var p=player(srv);GoetiaPlayer.set(p,"purity",0);GoetiaPlayer.set(p,"impurity",1000);});shot("goetia_demon_horns");
  client("JEI forge integration",20,mc->{mc.options.setCameraType(CameraType.FIRST_PERSON);var runtime=teamroots.goetia.compat.jei.GoetiaJei.runtime;check(runtime!=null,"JEI runtime available");check(runtime.getRecipeManager().createRecipeLookup(teamroots.goetia.compat.jei.GoetiaJei.TYPE).get().count()==2,"JEI exposes two demon forge recipes");runtime.getRecipesGui().showTypes(java.util.List.of(teamroots.goetia.compat.jei.GoetiaJei.TYPE));});shot("goetia_jei_forge");
  client("all item models",20,mc->mc.gui.setScreen(new net.minecraft.client.gui.screens.Screen(net.minecraft.network.chat.Component.literal("Goetia released items")){
   @Override public boolean isPauseScreen(){return false;}
   @Override public void extractRenderState(net.minecraft.client.gui.GuiGraphicsExtractor g,int mx,int my,float partial){g.fill(0,0,width,height,0xFF202020);g.text(mc.font,title,12,10,0xFFFFFFFF,false);var items=net.minecraft.core.registries.BuiltInRegistries.ITEM.entrySet().stream().filter(e->e.getKey().identifier().getNamespace().equals("goetia")).sorted(java.util.Comparator.comparing(e->e.getKey().identifier().toString())).toList();for(int i=0;i<items.size();i++)g.item(new ItemStack(items.get(i).getValue()),16+(i%12)*24,36+(i/12)*24);}
  }));shot("goetia_item_catalogue");
  client("resume before placing world blocks",20,mc->{mc.gui.setScreen(null);mc.options.setCameraType(CameraType.FIRST_PERSON);});
  server("placed ritual and water scene",40,srv->{var p=player(srv);var w=p.level();var altar=new BlockPos(-4,101,0);w.setBlockAndUpdate(altar,GoetiaContent.block("altar").defaultBlockState());w.setBlockAndUpdate(altar.above(),GoetiaContent.block("full_bowl").defaultBlockState());var bowl=(GoetiaBlockData)w.getBlockEntity(altar.above());bowl.color=0xB02030;bowl.entity="minecraft:cow";bowl.changed();for(int dz:new int[]{-1,1}){w.setBlockAndUpdate(altar.offset(0,0,dz),Blocks.STONE.defaultBlockState());w.setBlockAndUpdate(altar.offset(0,1,dz),GoetiaContent.block(dz<0?"angel_candle_stand":"demon_candle_stand").defaultBlockState());}w.setBlockAndUpdate(new BlockPos(-7,101,0),GoetiaContent.block("empty_bowl").defaultBlockState());w.setBlockAndUpdate(new BlockPos(-2,101,6),Blocks.STONE.defaultBlockState());w.setBlockAndUpdate(new BlockPos(0,101,6),Blocks.STONE.defaultBlockState());w.setBlockAndUpdate(new BlockPos(-2,102,6),GoetiaContent.block("block_angel_lost_note").defaultBlockState());w.setBlockAndUpdate(new BlockPos(0,102,6),GoetiaContent.block("block_demon_lost_note").defaultBlockState());String[] candles={"candle","candle_stand","angel_candle","angel_candle_stand","demon_candle","demon_candle_stand"};for(int i=0;i<candles.length;i++)w.setBlockAndUpdate(new BlockPos(-6+i*2,101,3),GoetiaContent.block(candles[i]).defaultBlockState());for(int x=4;x<=6;x++)for(int z=0;z<=2;z++){w.setBlockAndUpdate(new BlockPos(x,99,z),Blocks.STONE.defaultBlockState());w.setBlockAndUpdate(new BlockPos(x,100,z),GoetiaFluids.BLOCK.get().defaultBlockState());}p.getAbilities().flying=true;p.onUpdateAbilities();p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.teleportTo(w,0,108,10,java.util.Set.of(),180,40,false);});
  client("placed block synchronization",5,mc->{mc.gui.setScreen(null);mc.options.setCameraType(CameraType.FIRST_PERSON);check(mc.level.getBlockEntity(new BlockPos(-4,102,0)) instanceof GoetiaBlockData d&&d.color==0xB02030,"blood bowl color reaches actual client block entity: block="+mc.level.getBlockState(new BlockPos(-4,102,0))+" entity="+mc.level.getBlockEntity(new BlockPos(-4,102,0))+" color="+(mc.level.getBlockEntity(new BlockPos(-4,102,0)) instanceof GoetiaBlockData b?Integer.toHexString(b.color):"none"));check(mc.level.getFluidState(new BlockPos(5,100,1)).getType()==GoetiaFluids.SOURCE.get(),"holy water source reaches actual client world");check(mc.level.getBlockState(new BlockPos(-2,102,6)).is(GoetiaContent.block("block_angel_lost_note"))&&mc.level.getBlockState(new BlockPos(0,102,6)).is(GoetiaContent.block("block_demon_lost_note")),"both physical note blocks reach client and visual scene");});shot("goetia_ritual_scene");
  server("spawn tracked fixed-power fireball",20,srv->{var p=player(srv);var w=p.level();var shot=new net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball(w,p,new net.minecraft.world.phys.Vec3(1,0,0),1);GoetiaFireballs.start(shot,new net.minecraft.world.phys.Vec3(1,0,0));shot.setPos(0,120,0);w.addFreshEntity(shot);fireballId=shot.getId();});
  client("fireball network state",5,mc->{var shot=mc.level.getEntity(fireballId);check(shot instanceof net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball,"vanilla fireball spawn reaches client");var flight=(LegacyFireballFlight)shot;check(flight.goetia$hasFlight()&&Math.abs(flight.goetia$power().length()-.1)<1e-6,"fixed fireball acceleration reaches client");check(shot.getDeltaMovement().lengthSqr()>0,"tracked client fireball moves");});
  server("punch tracked fireball",20,srv->{var p=player(srv);var shot=(net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball)p.level().getEntity(fireballId);p.setYRot(90);p.setXRot(0);redirectedPower=p.getLookAngle().scale(.1);p.attack(shot);check(shot.getOwner()==p&&((LegacyFireballFlight)shot).goetia$power().distanceTo(redirectedPower)<1e-6,"actual player attack redirects tracked fireball");});
  client("punched power synchronization",5,mc->{var shot=mc.level.getEntity(fireballId);check(shot instanceof net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball&&((LegacyFireballFlight)shot).goetia$power().distanceTo(redirectedPower)<1e-6,"changed fireball direction reaches tracking client");});
  client("rendered target state",5,mc->{check(GoetiaPlayer.alignment(mc.player)==GoetiaPlayer.Alignment.DEMON,"client sees demon alignment");check(mc.mouseHandler.isMouseGrabbed()==false,"client never grabs mouse");});
 }
 private static net.minecraft.client.input.MouseButtonEvent mouse(double x,double y,int button){return new net.minecraft.client.input.MouseButtonEvent(x,y,new net.minecraft.client.input.MouseButtonInfo(button,0));}
 private GoetiaHarness(){}
}
